-- Firefly pricing database export.
-- Generated by scripts/export_database_sql.py.
BEGIN;
SET client_encoding = 'UTF8';
SET session_replication_role = replica;

DROP TABLE IF EXISTS "agent_runs" CASCADE;
DROP TABLE IF EXISTS "price_revisions" CASCADE;
DROP TABLE IF EXISTS "pricing_rules" CASCADE;
DROP TABLE IF EXISTS "price_items" CASCADE;
DROP TABLE IF EXISTS "source_records" CASCADE;
DROP TABLE IF EXISTS "source_documents" CASCADE;
DROP TABLE IF EXISTS "products" CASCADE;
DROP TABLE IF EXISTS "product_categories" CASCADE;
DROP TABLE IF EXISTS "change_logs" CASCADE;
DROP TABLE IF EXISTS "requirement_jobs" CASCADE;
DROP TABLE IF EXISTS "customer_files" CASCADE;
DROP TABLE IF EXISTS "quote_drafts" CASCADE;
DROP TABLE IF EXISTS "extraction_runs" CASCADE;
DROP TABLE IF EXISTS "alembic_version" CASCADE;


CREATE TABLE alembic_version (
	version_num VARCHAR(32) NOT NULL, 
	CONSTRAINT alembic_version_pkc PRIMARY KEY (version_num)
)

;

CREATE TABLE change_logs (
	id SERIAL NOT NULL, 
	entity VARCHAR(40) NOT NULL, 
	entity_id INTEGER NOT NULL, 
	action VARCHAR(30) NOT NULL, 
	actor VARCHAR(100) NOT NULL, 
	reason TEXT NOT NULL, 
	before JSON, 
	after JSON, 
	created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	CONSTRAINT change_logs_pkey PRIMARY KEY (id)
)

;

CREATE TABLE product_categories (
	id SERIAL NOT NULL, 
	name VARCHAR(100) NOT NULL, 
	CONSTRAINT product_categories_pkey PRIMARY KEY (id), 
	CONSTRAINT product_categories_name_key UNIQUE NULLS DISTINCT (name)
)

;

CREATE TABLE requirement_jobs (
	id SERIAL NOT NULL, 
	title VARCHAR(150) NOT NULL, 
	customer VARCHAR(150) NOT NULL, 
	brief TEXT NOT NULL, 
	status VARCHAR(30) NOT NULL, 
	extraction JSON NOT NULL, 
	requirements JSON NOT NULL, 
	messages JSON NOT NULL, 
	revision INTEGER NOT NULL, 
	created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	updated_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	business_rules_version VARCHAR(30) NOT NULL, 
	CONSTRAINT requirement_jobs_pkey PRIMARY KEY (id)
)

;

CREATE TABLE source_documents (
	id SERIAL NOT NULL, 
	filename VARCHAR(255) NOT NULL, 
	sha256 VARCHAR(64) NOT NULL, 
	imported_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	report JSON NOT NULL, 
	CONSTRAINT source_documents_pkey PRIMARY KEY (id), 
	CONSTRAINT source_documents_sha256_key UNIQUE NULLS DISTINCT (sha256)
)

;

CREATE TABLE agent_runs (
	id SERIAL NOT NULL, 
	job_id INTEGER NOT NULL, 
	status VARCHAR(30) NOT NULL, 
	model VARCHAR(100) NOT NULL, 
	steps JSON NOT NULL, 
	usage JSON NOT NULL, 
	message TEXT NOT NULL, 
	created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	finished_at TIMESTAMP WITHOUT TIME ZONE, 
	CONSTRAINT agent_runs_pkey PRIMARY KEY (id), 
	CONSTRAINT agent_runs_job_id_fkey FOREIGN KEY(job_id) REFERENCES requirement_jobs (id)
)

;

CREATE TABLE customer_files (
	id SERIAL NOT NULL, 
	job_id INTEGER NOT NULL, 
	filename VARCHAR(255) NOT NULL, 
	sha256 VARCHAR(64) NOT NULL, 
	storage_key VARCHAR(100) NOT NULL, 
	media_type VARCHAR(100) NOT NULL, 
	byte_size INTEGER NOT NULL, 
	page_count INTEGER NOT NULL, 
	created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	CONSTRAINT customer_files_pkey PRIMARY KEY (id), 
	CONSTRAINT customer_files_job_id_fkey FOREIGN KEY(job_id) REFERENCES requirement_jobs (id)
)

;

CREATE TABLE extraction_runs (
	id SERIAL NOT NULL, 
	job_id INTEGER NOT NULL, 
	status VARCHAR(30) NOT NULL, 
	model VARCHAR(100) NOT NULL, 
	attempts INTEGER NOT NULL, 
	usage JSON NOT NULL, 
	error TEXT NOT NULL, 
	input_revision INTEGER NOT NULL, 
	created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	finished_at TIMESTAMP WITHOUT TIME ZONE, 
	CONSTRAINT extraction_runs_pkey PRIMARY KEY (id), 
	CONSTRAINT extraction_runs_job_id_fkey FOREIGN KEY(job_id) REFERENCES requirement_jobs (id)
)

;

CREATE TABLE products (
	id SERIAL NOT NULL, 
	category_id INTEGER NOT NULL, 
	name VARCHAR(150) NOT NULL, 
	CONSTRAINT products_pkey PRIMARY KEY (id), 
	CONSTRAINT products_category_id_fkey FOREIGN KEY(category_id) REFERENCES product_categories (id), 
	CONSTRAINT products_category_id_name_key UNIQUE NULLS DISTINCT (category_id, name)
)

;

CREATE TABLE quote_drafts (
	id SERIAL NOT NULL, 
	job_id INTEGER NOT NULL, 
	version INTEGER NOT NULL, 
	job_revision INTEGER NOT NULL, 
	status VARCHAR(20) NOT NULL, 
	payload JSON NOT NULL, 
	terms TEXT NOT NULL, 
	approval_note TEXT NOT NULL, 
	created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	approved_at TIMESTAMP WITHOUT TIME ZONE, 
	CONSTRAINT quote_drafts_pkey PRIMARY KEY (id), 
	CONSTRAINT quote_drafts_job_id_fkey FOREIGN KEY(job_id) REFERENCES requirement_jobs (id), 
	CONSTRAINT quote_drafts_job_id_version_key UNIQUE NULLS DISTINCT (job_id, version)
)

;

CREATE TABLE source_records (
	id SERIAL NOT NULL, 
	document_id INTEGER NOT NULL, 
	sheet VARCHAR(150) NOT NULL, 
	row_number INTEGER NOT NULL, 
	cells JSON NOT NULL, 
	CONSTRAINT source_records_pkey PRIMARY KEY (id), 
	CONSTRAINT source_records_document_id_fkey FOREIGN KEY(document_id) REFERENCES source_documents (id), 
	CONSTRAINT source_records_document_id_sheet_row_number_key UNIQUE NULLS DISTINCT (document_id, sheet, row_number)
)

;

CREATE TABLE price_items (
	id SERIAL NOT NULL, 
	product_id INTEGER NOT NULL, 
	material VARCHAR(100) NOT NULL, 
	thickness_mm NUMERIC(10, 3), 
	spec VARCHAR(255) NOT NULL, 
	language VARCHAR(20) NOT NULL, 
	process VARCHAR(255) NOT NULL, 
	quality VARCHAR(100) NOT NULL, 
	unit VARCHAR(20) NOT NULL, 
	amount NUMERIC(18, 6), 
	price_kind VARCHAR(20) NOT NULL, 
	status VARCHAR(20) NOT NULL, 
	notes TEXT NOT NULL, 
	review_reason TEXT NOT NULL, 
	attributes JSON NOT NULL, 
	source_record_id INTEGER, 
	source_cell VARCHAR(40) NOT NULL, 
	revision INTEGER NOT NULL, 
	created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	updated_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	CONSTRAINT price_items_pkey PRIMARY KEY (id), 
	CONSTRAINT price_items_product_id_fkey FOREIGN KEY(product_id) REFERENCES products (id), 
	CONSTRAINT price_items_source_record_id_fkey FOREIGN KEY(source_record_id) REFERENCES source_records (id)
)

;

CREATE TABLE pricing_rules (
	id SERIAL NOT NULL, 
	product_id INTEGER, 
	name VARCHAR(255) NOT NULL, 
	content TEXT NOT NULL, 
	rule_type VARCHAR(30) NOT NULL, 
	status VARCHAR(20) NOT NULL, 
	source_record_id INTEGER, 
	source_cell VARCHAR(40) NOT NULL, 
	revision INTEGER NOT NULL, 
	updated_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	CONSTRAINT pricing_rules_pkey PRIMARY KEY (id), 
	CONSTRAINT pricing_rules_product_id_fkey FOREIGN KEY(product_id) REFERENCES products (id), 
	CONSTRAINT pricing_rules_source_record_id_fkey FOREIGN KEY(source_record_id) REFERENCES source_records (id)
)

;

CREATE TABLE price_revisions (
	id SERIAL NOT NULL, 
	price_item_id INTEGER NOT NULL, 
	revision INTEGER NOT NULL, 
	snapshot JSON NOT NULL, 
	reason TEXT NOT NULL, 
	created_at TIMESTAMP WITHOUT TIME ZONE NOT NULL, 
	CONSTRAINT price_revisions_pkey PRIMARY KEY (id), 
	CONSTRAINT price_revisions_price_item_id_fkey FOREIGN KEY(price_item_id) REFERENCES price_items (id), 
	CONSTRAINT price_revisions_price_item_id_revision_key UNIQUE NULLS DISTINCT (price_item_id, revision)
)

;

